#!/usr/bin/env bash
set -Eeuo pipefail

# HYPER-HOST CS16 SQL ACCESS PANEL v1
# Adds phpMyAdmin access to each dedicated game SQL DB and optional external MySQL access.

ROOT="${1:-/root/hyper-hosting-panel}"
SID="${2:-25}"
DOMAIN="${3:-www.avito.hyper-host.pw}"

SRC_CTL="$ROOT/cs16-panel/bin/hyper-cs16-ctl"
SRC_UI="$ROOT/cs16-panel/public/index.php"
LIVE_CTL="/usr/local/sbin/hyper-cs16-ctl"
LIVE_UI="/var/www/hyper-host-sites/${DOMAIN}/public_html/index.php"
DOCROOT="/var/www/hyper-host-sites/${DOMAIN}/public_html"
PMA_DIR="$DOCROOT/phpmyadmin"

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-sql-access-v1-${STAMP}"
TMPDIR="$(mktemp -d /tmp/hyper-cs16-sql-access.XXXXXX)"
PATCHER="$TMPDIR/patch.py"

cleanup(){ rm -rf "$TMPDIR"; }
trap cleanup EXIT

[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] Run with sudo/root"; exit 1; }

for f in "$SRC_CTL" "$SRC_UI" "$LIVE_CTL" "$LIVE_UI"; do
    [[ -f "$f" ]] || { echo "[ERROR] Missing $f"; exit 2; }
done

mkdir -p "$BACKUP"
cp -a "$SRC_CTL" "$BACKUP/hyper-cs16-ctl.repo"
cp -a "$SRC_UI" "$BACKUP/index.repo.php"
cp -a "$LIVE_CTL" "$BACKUP/hyper-cs16-ctl.live"
cp -a "$LIVE_UI" "$BACKUP/index.live.php"

echo "============================================================"
echo " HYPER-HOST CS16 SQL ACCESS PANEL v1"
echo " Repo:   $ROOT"
echo " Server: #$SID"
echo " Panel:  $DOMAIN"
echo " Backup: $BACKUP"
echo "============================================================"

base64 -d >"$PATCHER" <<'PATCH_B64'

PATCH_B64

echo "[1/7] Validating patcher..."
python3 -m py_compile "$PATCHER"

echo "[2/7] Patching repo + live panel/controller..."
python3 "$PATCHER" "$SRC_CTL" "$LIVE_CTL" "$SRC_UI" "$LIVE_UI"

echo "[3/7] Syntax checks..."
python3 -m py_compile "$SRC_CTL"
python3 -m py_compile "$LIVE_CTL"
php -l "$SRC_UI" >/dev/null
php -l "$LIVE_UI" >/dev/null
chmod 0755 "$SRC_CTL" "$LIVE_CTL"

echo "[4/7] Installing phpMyAdmin..."
DEBIAN_FRONTEND=noninteractive apt-get update -y >/dev/null
DEBIAN_FRONTEND=noninteractive apt-get install -y \
    curl ca-certificates tar openssl php-mysql php-mbstring php-xml php-zip php-gd php-curl >/dev/null

if [[ ! -f "$PMA_DIR/index.php" ]]; then
    curl -fL --retry 3 --connect-timeout 20 \
      "https://www.phpmyadmin.net/downloads/phpMyAdmin-latest-all-languages.tar.gz" \
      -o "$TMPDIR/phpmyadmin.tar.gz"
    tar -xzf "$TMPDIR/phpmyadmin.tar.gz" -C "$TMPDIR"
    PMA_SRC="$(find "$TMPDIR" -maxdepth 1 -type d -name 'phpMyAdmin-*' | head -1)"
    [[ -n "$PMA_SRC" && -f "$PMA_SRC/index.php" ]] || { echo "[ERROR] phpMyAdmin archive invalid"; exit 3; }
    if [[ -e "$PMA_DIR" ]]; then
        mv "$PMA_DIR" "$BACKUP/phpmyadmin.previous"
    fi
    mv "$PMA_SRC" "$PMA_DIR"
fi

mkdir -p "$PMA_DIR/tmp"
SECRET="$(openssl rand -hex 32)"
cat >"$PMA_DIR/config.inc.php" <<PHP
<?php
\$cfg['blowfish_secret'] = '${SECRET}';
\$i = 1;
\$cfg['Servers'][\$i]['auth_type'] = 'cookie';
\$cfg['Servers'][\$i]['host'] = '127.0.0.1';
\$cfg['Servers'][\$i]['port'] = '3306';
\$cfg['Servers'][\$i]['compress'] = false;
\$cfg['Servers'][\$i]['AllowNoPassword'] = false;
\$cfg['Servers'][\$i]['AllowRoot'] = false;
\$cfg['AllowArbitraryServer'] = false;
\$cfg['LoginCookieValidity'] = 14400;
\$cfg['TempDir'] = __DIR__ . '/tmp';
\$cfg['ShowPhpInfo'] = false;
PHP

chown -R www-data:www-data "$PMA_DIR"
find "$PMA_DIR" -type d -exec chmod 0755 {} +
find "$PMA_DIR" -type f -exec chmod 0644 {} +
chmod 0770 "$PMA_DIR/tmp"

echo "[5/7] Verifying new controller commands..."
"$LIVE_CTL" --help 2>&1 | grep -q 'sql-external-status' || { echo "[ERROR] sql-external-status not registered"; exit 4; }
"$LIVE_CTL" --help 2>&1 | grep -q 'sql-external-enable' || { echo "[ERROR] sql-external-enable not registered"; exit 4; }
"$LIVE_CTL" --help 2>&1 | grep -q 'sql-external-disable' || { echo "[ERROR] sql-external-disable not registered"; exit 4; }

echo "--- SQL STATUS ---"
"$LIVE_CTL" sql-status "$SID" || true
echo "--- EXTERNAL STATUS ---"
"$LIVE_CTL" sql-external-status "$SID" || true

echo "[6/7] Reloading PHP-FPM..."
while read -r svc; do
    [[ -n "$svc" ]] || continue
    systemctl reload "$svc" 2>/dev/null || systemctl restart "$svc" 2>/dev/null || true
done < <(systemctl list-units --type=service --state=running --no-legend | awk '/php.*fpm/ {print $1}')

echo "[7/7] phpMyAdmin HTTP check..."
HTTP_CODE="$(curl -sS -o /dev/null -w '%{http_code}' -H "Host: $DOMAIN" "http://127.0.0.1/phpmyadmin/" || true)"
echo "phpMyAdmin HTTP=$HTTP_CODE"
if [[ "$HTTP_CODE" != "200" && "$HTTP_CODE" != "302" ]]; then
    echo "[WARN] phpMyAdmin files are installed, but nginx returned HTTP $HTTP_CODE."
    echo "[WARN] Open http://$DOMAIN/phpmyadmin/ manually. If it is 404, send nginx -T for this vhost."
fi

echo
echo "============================================================"
echo "[SUCCESS] CS16 SQL ACCESS PANEL v1 INSTALLED"
echo
echo "Panel:"
echo "  CS 1.6 server -> SQL"
echo
echo "There you now have:"
echo "  - real DB / user / password"
echo "  - Open phpMyAdmin button"
echo "  - optional external MySQL access for ONE exact IPv4"
echo
echo "phpMyAdmin:"
echo "  http://$DOMAIN/phpmyadmin/"
echo
echo "No website patch is required for this feature."
echo "Backup:"
echo "  $BACKUP"
echo "============================================================"
